945  bool X86_getInstruction(csh ud, const uint8_t *code, size_t code_len,
   946                  MCInst *instr, uint16_t *size, uint64_t address, void *_info)
   947  {
   948          cs_struct *handle = (cs_struct *)(uintptr_t)ud;
   949          InternalInstruction insn = { 0 };
   950          struct reader_info info;
   951          int ret;
   952          bool result;
   953
   954          info.code = code;
   955          info.size = code_len;
   956          info.offset = address;
   957
   958          if (instr->flat_insn->detail) {
   959                  // instr->flat_insn->detail initialization: 3 alternatives
   960
   961                  // 1. The whole structure, this is how it's done in other arch disassemblers
   962                  // Probably overkill since cs_detail is huge because of the 36 operands of ARM
   963
   964                  //memset(instr->flat_insn->detail, 0, sizeof(cs_detail));
   965
   966                  // 2. Only the part relevant to x86
   967                  memset(instr->flat_insn->detail, 0, offsetof(cs_detail, x86) + sizeof(cs_x86));
   968
   969                  // 3. The relevant part except for x86.operands
   970                  // sizeof(cs_x86) is 0x1c0, sizeof(x86.operands) is 0x180
   971                  // marginally faster, should be okay since x86.op_count is set to 0
   972
   973                  //memset(instr->flat_insn->detail, 0, offsetof(cs_detail, x86)+offsetof(cs_x86, operands));
   974          }
   975
   976          if (handle->mode & CS_MODE_16)
   977                  ret = decodeInstruction(&insn,
   978                                  reader, &info,
   979                                  address,
   980                                  MODE_16BIT);
   981          else if (handle->mode & CS_MODE_32)
   982                  ret = decodeInstruction(&insn,
   983                                  reader, &info,
   984                                  address,
   985                                  MODE_32BIT);
   986          else
   987                  ret = decodeInstruction(&insn,
   988                                  reader, &info,
   989                                  address,
   990                                  MODE_64BIT);
   991
   992          if (ret) {
   993                  // *size = (uint16_t)(insn.readerCursor - address);
   994                  return false;
   995          } else {
   996                  *size = (uint16_t)insn.length;
   997
   998                  result = (!translateInstruction(instr, &insn)) ?  true : false;
   999                  if (result) {
  1000                          unsigned Flags = X86_IP_NO_PREFIX;
  1001                          instr->imm_size = insn.immSize;
  1002                          if (handle->detail) {
  1003                                  update_pub_insn(instr->flat_insn, &insn, instr->x86_prefix);
  1004                          } else {
  1005                                  // still copy all prefixes
  1006                                  instr->x86_prefix[0] = insn.prefix0;
  1007                                  instr->x86_prefix[1] = insn.prefix1;
  1008                                  instr->x86_prefix[2] = insn.prefix2;
  1009                                  instr->x86_prefix[3] = insn.prefix3;
  1010                          }
  1011
  1012                          if (insn.hasAdSize)
  1013                                  Flags |= X86_IP_HAS_AD_SIZE;
  1014
  1015                          if (!insn.mandatoryPrefix) {
  1016                                  if (insn.hasOpSize)
  1017                                          Flags |= X86_IP_HAS_OP_SIZE;
  1018
  1019                                  if (insn.repeatPrefix == 0xf2)
  1020                                          Flags |= X86_IP_HAS_REPEAT_NE;
  1021                                  else if (insn.repeatPrefix == 0xf3 &&
  1022                                                  // It should not be 'pause' f3 90
  1023                                                  insn.opcode != 0x90)
  1024                                          Flags |= X86_IP_HAS_REPEAT;
  1025                                  if (insn.hasLockPrefix)
  1026                                          Flags |= X86_IP_HAS_LOCK;
  1027                          }
  1028
  1029                          instr->flags = Flags;
  1030                  }
  1031
  1032                  return result;
  1033          }
  1034  }
  1035
