   844  size_t CAPSTONE_API cs_disasm(csh ud, const uint8_t *buffer, size_t size, uint64_t offset, size_t count, cs_insn **insn)
   845  {
   846          struct cs_struct *handle;
   847          MCInst mci;
   848          uint16_t insn_size;
   849          size_t c = 0, i;
   850          unsigned int f = 0;     // index of the next instruction in the cache
   851          cs_insn *insn_cache;    // cache contains disassembled instructions
   852          void *total = NULL;
   853          size_t total_size = 0;  // total size of output buffer containing all insns
   854          bool r;
   855          void *tmp;
   856          size_t skipdata_bytes;
   857          uint64_t offset_org; // save all the original info of the buffer
   858          size_t size_org;
   859          const uint8_t *buffer_org;
   860          unsigned int cache_size = INSN_CACHE_SIZE;
   861          size_t next_offset;
   862
   863          handle = (struct cs_struct *)(uintptr_t)ud;
   864          if (!handle) {
   865                  // FIXME: how to handle this case:
   866                  // handle->errnum = CS_ERR_HANDLE;
   867                  return 0;
   868          }
   869
   870          handle->errnum = CS_ERR_OK;
   871
   872          // reset IT block of ARM structure
   873          if (handle->arch == CS_ARCH_ARM)
   874                  handle->ITBlock.size = 0;
   875
   876  #ifdef CAPSTONE_USE_SYS_DYN_MEM
   877          if (count > 0 && count <= INSN_CACHE_SIZE)
   878                  cache_size = (unsigned int) count;
   879  #endif
   880
   881          // save the original offset for SKIPDATA
   882          buffer_org = buffer;
   883          offset_org = offset;
   884          size_org = size;
   885
   886          total_size = sizeof(cs_insn) * cache_size;
   887          total = cs_mem_malloc(total_size);
   888          if (total == NULL) {
   889                  // insufficient memory
   890                  handle->errnum = CS_ERR_MEM;
   891                  return 0;
   892          }
   893
   894          insn_cache = total;
   895
   896          while (size > 0) {
   897                  MCInst_Init(&mci);
   898                  mci.csh = handle;
   899
   900                  // relative branches need to know the address & size of current insn
   901                  mci.address = offset;
   902
   903                  if (handle->detail) {
   904                          // allocate memory for @detail pointer
   905                          insn_cache->detail = cs_mem_malloc(sizeof(cs_detail));
   906                  } else {
   907                          insn_cache->detail = NULL;
   908                  }
   909
   910                  // save all the information for non-detailed mode
   911                  mci.flat_insn = insn_cache;
   912                  mci.flat_insn->address = offset;
   913  #ifdef CAPSTONE_DIET
   914                  // zero out mnemonic & op_str
   915                  mci.flat_insn->mnemonic[0] = '\0';
   916                  mci.flat_insn->op_str[0] = '\0';
   917  #endif
   918
   919                  r = handle->disasm(ud, buffer, size, &mci, &insn_size, offset, handle->getinsn_info);
   920                  if (r) {
   921                          SStream ss;
   922                          SStream_Init(&ss);
   923
   924                          mci.flat_insn->size = insn_size;
   925
   926                          // map internal instruction opcode to public insn ID
   927
   928                          handle->insn_id(handle, insn_cache, mci.Opcode);
   929
   930                          handle->printer(&mci, &ss, handle->printer_info);
   931
   932                          fill_insn(handle, insn_cache, ss.buffer, &mci, handle->post_printer, buffer);
   933
   934                          // adjust for pseudo opcode (X86)
   935                          if (handle->arch == CS_ARCH_X86)
   936                                  insn_cache->id += mci.popcode_adjust;
   937
   938                          next_offset = insn_size;
   939                  } else  {
   940                          // encounter a broken instruction
   941
   942                          // free memory of @detail pointer
   943                          if (handle->detail) {
   944                                  cs_mem_free(insn_cache->detail);
   945                          }
   946
   947                          // if there is no request to skip data, or remaining data is too small,
   948                          // then bail out
   949                          if (!handle->skipdata || handle->skipdata_size > size)
   950                                  break;
   951
   952                          if (handle->skipdata_setup.callback) {
   953                                  skipdata_bytes = handle->skipdata_setup.callback(buffer_org, size_org,
   954                                                  (size_t)(offset - offset_org), handle->skipdata_setup.user_data);
   955                                  if (skipdata_bytes > size)
   956                                          // remaining data is not enough
   957                                          break;
   958
   959                                  if (!skipdata_bytes)
   960                                          // user requested not to skip data, so bail out
   961                                          break;
   962                          } else
   963                                  skipdata_bytes = handle->skipdata_size;
   964
   965                          // we have to skip some amount of data, depending on arch & mode
   966                          insn_cache->id = 0;     // invalid ID for this "data" instruction
   967                          insn_cache->address = offset;
   968                          insn_cache->size = (uint16_t)skipdata_bytes;
   969                          memcpy(insn_cache->bytes, buffer, skipdata_bytes);
   970  #ifdef CAPSTONE_DIET
   971                          insn_cache->mnemonic[0] = '\0';
   972                          insn_cache->op_str[0] = '\0';
   973  #else
   974                          strncpy(insn_cache->mnemonic, handle->skipdata_setup.mnemonic,
   975                                          sizeof(insn_cache->mnemonic) - 1);
   976                          skipdata_opstr(insn_cache->op_str, buffer, skipdata_bytes);
   977  #endif
   978                          insn_cache->detail = NULL;
   979
   980                          next_offset = skipdata_bytes;
